package cli

// Characterization tests pinning the non-interactive byte contracts
// (issue #62): `check`, `check --json`, `scan --json`, `apply --yes`,
// `apply --dry-run`, and the bare picker's non-TTY fallback must be
// byte-identical to base 521fedf. Every scenario runs a fully stubbed
// App against temp paths — no real installers, no real config, no real
// state. The goldens in testdata/compat62/ were generated by running
// this exact file on the base revision:
//
//	GOLDEN62_UPDATE=1 go test ./internal/cli/ -run TestCompat62_Goldens
//
// On this branch the test runs WITHOUT the env var and must pass
// unchanged: same bytes, same exit codes, scenario for scenario.

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"ofa/internal/detect"
	"ofa/internal/resolve"
	"ofa/internal/update"
)

// compat62Fixture returns a fixed, deterministic pipeline answer: one
// self-updater, one outdated npm install, one at-latest install. No
// scenario pins or shadows anything, so nothing takes a skip path —
// those are covered by focused tests elsewhere.
func compat62Fixture(a *App, sd *stubDetect, sr *stubResolve) {
	// Pin the clock: state timestamps and cache ages must not vary
	// between the base run that minted the goldens and later runs.
	a.Now = func() time.Time { return mustTime("2025-01-01T00:00:00Z") }
	sd.instances = oneClaude()
	sd.instances = append(sd.instances,
		detect.Instance{HarnessID: "qwen", Method: "npm", Package: "@qwen-code/qwen-code", Bin: "qwen", Version: "0.22.1", Status: detect.Active},
		detect.Instance{HarnessID: "codex", Method: "brew-cask", Package: "codex", Bin: "codex", Version: "0.162.1", Status: detect.Active},
	)
	sr.res = []resolve.Resolution{
		{HarnessID: "claude", Method: "native", Bin: "claude", Cur: "2.1.300", Tier: "self"},
		{HarnessID: "qwen", Method: "npm", Package: "@qwen-code/qwen-code", Bin: "qwen", Cur: "0.22.1", Latest: "0.25.2", Outdated: true, Tier: "npm"},
		{HarnessID: "codex", Method: "brew-cask", Package: "codex", Bin: "codex", Cur: "0.162.1", Latest: "0.162.1", Tier: "brew"},
	}
}

func TestCompat62_Goldens(t *testing.T) {
	cases := []struct {
		name  string
		args  []string
		setup func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec)
	}{
		{name: "check", args: []string{"check"},
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) { compat62Fixture(a, sd, sr) }},
		{name: "check-json", args: []string{"check", "--json"},
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) { compat62Fixture(a, sd, sr) }},
		{name: "scan-json", args: []string{"scan", "--json"},
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) { compat62Fixture(a, sd, sr) }},
		{name: "apply-yes", args: []string{"apply", "--yes"},
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) {
				compat62Fixture(a, sd, sr)
				se.results["claude (native)"] = update.Result{Label: "claude (native)", ExitCode: 0}
				se.results["qwen (npm)"] = update.Result{Label: "qwen (npm)", Failed: true, Err: errString("stub failure"), ExitCode: 1, OutputTail: "stub tail"}
			}},
		{name: "apply-dry-run", args: []string{"apply", "--dry-run"},
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) {
				compat62Fixture(a, sd, sr)
				se.results["claude (native)"] = update.Result{Label: "claude (native)", ExitCode: 0}
				se.results["qwen (npm)"] = update.Result{Label: "qwen (npm)", ExitCode: 0}
			}},
		// The bare picker's non-TTY fallback: first-run scan notice and
		// the no-TTY message, plain bytes only.
		{name: "bare-no-tty", args: nil,
			setup: func(a *App, sd *stubDetect, sr *stubResolve, se *stubExec) {
				compat62Fixture(a, sd, sr)
				a.StatePath = missingStatePath(t)
			}},
	}

	regen := os.Getenv("GOLDEN62_UPDATE") == "1"
	dir := filepath.Join("testdata", "compat62")
	if regen {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", dir, err)
		}
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			a, stdout, stderr, sd, sr, se := newTestApp(t, tc.args, nil)
			if tc.setup != nil {
				tc.setup(a, sd, sr, se)
			}
			code := a.Run()

			// Normalize the two temp directories newTestApp creates (the
			// state file and the absent user-catalog dir): they carry
			// per-process random components and appear in nothing but
			// the odd diagnostic. Everything else is compared verbatim.
			norm := func(s string) string {
				for _, d := range []string{filepath.Dir(a.StatePath), a.CatalogDir} {
					s = strings.ReplaceAll(s, d, "${TMP}")
				}
				return s
			}
			got := "--- stdout ---\n" + norm(stdout.String()) +
				"--- stderr ---\n" + norm(stderr.String()) +
				"--- exit ---\n" + strconv.Itoa(int(code))

			path := filepath.Join(dir, tc.name+".golden")
			if regen {
				if err := os.WriteFile(path, []byte(got), 0o644); err != nil {
					t.Fatalf("write golden: %v", err)
				}
				return
			}
			want, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("read golden (regenerate on base with GOLDEN62_UPDATE=1): %v", err)
			}
			if got != string(want) {
				t.Errorf("output differs from base 521fedf golden:\n=== got ===\n%s\n=== want ===\n%s", got, want)
			}
		})
	}
}

// errString is a comparable error for canned stub results.
type errString string

func (e errString) Error() string { return string(e) }
